const RX=[[/^⏳ Sondaggio aperto — chiude tra: (\d+)g (\d+)h (\d+)m (\d+)s$/,"⏳ Survey open — closes in: $1d $2h $3m $4s"],[/^⬤ Loggato come (.+)$/,"⬤ Logged in as $1"],[/^📅 Iscritto il (.+)$/,"📅 Joined on $1"],[/^Documento (\d+) di (\d+)$/,"Document $1 of $2"],[/^Screenshot (\d+) di (.+)$/,"Screenshot $1 of $2"]];
const T={en:EN};
if(L!="it"&&!T[L]){L="en";window.ETA_LANG=L}
const norm=s=>s.replace(/\s+/g," ").trim();
const tr=s=>{const D=T[L];if(!D||typeof s!="string")return s;const n=norm(s);if(!n)return s;const lead=s.match(/^\s*/)[0],trail=s.match(/\s*$/)[0];
let v=D[n];
if(!v){const m=n.match(/^(.*?)(\s\(\d+\))$/);if(m&&D[m[1]])v=D[m[1]]+m[2]}
if(!v){const m=n.match(/^(\[[^\]]*\]\s)(.+)$/);if(m&&D[m[2]])v=m[1]+D[m[2]]}
if(!v)for(const[r,o]of RX)if(r.test(n)){v=n.replace(r,o);break}
return v?lead+v+trail:s};
